package dev.zomboid.survival;import java.util.*;import dev.zomboid.decor.Checks.*;public class MachineEntity {public static final Map<Object,Set<P>> GENERATORS=new WeakHashMap<>();public int burn=100,changes;public boolean queued;public int getContainerSize(){return 1;}public Fuel getItem(int slot){return new Fuel(queued);}public record Fuel(boolean queued){public int getBurnTime(Object recipe){return queued?1600:0;}}public Energy energy=new Energy();public int zsGetBurn(){return burn;}public void setChanged(){changes++;}public static class Energy{public int stored=40000,extracted;public int extractEnergy(int n,boolean simulate){int take=Math.min(n,stored);if(!simulate){stored-=take;extracted+=take;}return take;}}}
